1	import { describe, it, expect } from "vitest";
2	import { mergeContact, type FetchedEntry } from "./merge";
3	
4	// A populated client-style file: frontmatter, a Mark's Email History section
5	// with one existing entry, and an mbox "## Email History" section that the tool
6	// must never touch.
7	const POPULATED = `---
8	last_name: Blyth
9	first_name: Don
10	email: "don@example.com"
11	last_updated: 2026-02-18
12	---
13	
14	## Mark's Email History
15	
16	### 2025-09-09
17	- **Subject:** Re: Rose and Crown
18	  - Direction: From friend
19	  - Thread: aaa
20	  - Message: msg-existing
21	
22	## Email History
23	
24	### 2021-01-01
25	- **Subject:** old mbox thing
26	  - Direction: From client
27	  - Thread: 123
28	  - Message-ID: <x@y>
29	`;
30	
31	// A legacy Cowork-populated file: the entry has Thread but NO Message id.
32	const LEGACY = `---
33	last_name: Uhl
34	first_name: Heather
35	email: "heather@example.com"
36	last_updated: 2026-02-14
37	---
38	
39	## Mark's Email History
40	
41	### 2024-05-29
42	- **Subject:** Re: Coffee
43	  - Direction: To client
44	  - Summary: Mark said hi.
45	  - Thread: thr-legacy
46	
47	## Email History
48	
49	### 2020-01-01
50	- **Subject:** ancient
51	  - Direction: From client
52	  - Thread: 999
53	  - Message-ID: <a@b>
54	`;
55	
56	// A placeholder file — searched before, nothing found.
57	const PLACEHOLDER = `---
58	last_name: Schram
59	first_name: Chelynne
60	email: "c@forces.gc.ca"
61	last_updated: 2026-02-02
62	---
63	
64	## Mark's Email History
65	
66	_No direct emails found between Mark and this client in Mark's Gmail (searched Feb 2026). All correspondence was handled by Heather._
67	
68	## Email History
69	
70	### 2025-03-28
71	- **Subject:** Re: Invoice
72	  - Direction: From client
73	  - Thread: 111
74	  - Message-ID: <z@z>
75	`;
76	
77	// A friends/colleagues file: Mark's Email History only, NO "## Email History".
78	const FRIEND_NO_MBOX = `---
79	last_name: DeVilla
80	first_name: Joey
81	email: "joey@example.com"
82	last_updated: 2026-02-15
83	---
84	
85	## Mark's Email History
86	
87	### 2025-03-10
88	- **Subject:** Re: Catching up
89	  - Direction: From friend
90	  - Summary: Joey suggested coffee.
91	  - Thread: abc
92	  - Message: msg-old
93	`;
94	
95	function entry(over: Partial<FetchedEntry>): FetchedEntry {
96	  return {
97	    ts: Date.parse("2026-06-26T12:00:00Z"),
98	    dateStr: "2026-06-26",
99	    subject: "Lunch?",
100	    direction: "From friend",
101	    threadId: "bbb",
102	    messageId: "msg-new",
103	    link: "https://mail.example/msg-new",
104	    ...over,
105	  };
106	}
107	
108	describe("mergeContact", () => {
109	  it("splices a new entry and leaves the mbox Email History section untouched", () => {
110	    const r = mergeContact(POPULATED, [entry({})], "2026-07-02");
111	
112	    expect(r.status).toBe("written");
113	    expect(r.added).toBe(1);
114	    // new entry present
115	    expect(r.content).toContain("### 2026-06-26");
116	    expect(r.content).toContain("Message: msg-new");
117	    // existing Mark entry preserved
118	    expect(r.content).toContain("Message: msg-existing");
119	    // the entire mbox section, verbatim, still there
120	    const mbox = POPULATED.slice(POPULATED.indexOf("## Email History"));
121	    expect(r.content).toContain(mbox);
122	  });
123	
124	  it("does not re-add an entry whose Message id is already present", () => {
125	    const dup = entry({ messageId: "msg-existing", subject: "changed subject", threadId: "aaa" });
126	    const r = mergeContact(POPULATED, [dup], "2026-07-02");
127	
128	    expect(r.added).toBe(0);
129	    // msg-existing appears exactly once
130	    expect(r.content.split("Message: msg-existing").length - 1).toBe(1);
131	    // the duplicate's altered subject was not written
132	    expect(r.content).not.toContain("changed subject");
133	  });
134	
135	  it("does not re-add a legacy entry (no Message id) matching date+subject+direction+thread", () => {
136	    const sameAsLegacy = entry({
137	      dateStr: "2024-05-29",
138	      ts: Date.parse("2024-05-29T09:00:00Z"),
139	      subject: "Re: Coffee",
140	      direction: "To client",
141	      threadId: "thr-legacy",
142	      messageId: "brand-new-id", // has an id, but matches the legacy 4-tuple
143	    });
144	    const r = mergeContact(LEGACY, [sameAsLegacy], "2026-07-02");
145	
146	    expect(r.added).toBe(0);
147	    expect(r.content).not.toContain("brand-new-id");
148	  });
149	
150	  it("orders entries newest-first, grouped by date with no duplicate date headers", () => {
151	    const fetched = [
152	      entry({ messageId: "m-new", dateStr: "2026-06-26", ts: Date.parse("2026-06-26T10:00:00Z"), subject: "newest" }),
153	      entry({ messageId: "m-old", dateStr: "2024-01-01", ts: Date.parse("2024-01-01T10:00:00Z"), subject: "oldest" }),
154	      entry({ messageId: "m-same", dateStr: "2025-09-09", ts: Date.parse("2025-09-09T23:00:00Z"), subject: "same day newer", direction: "To friend", threadId: "zzz" }),
155	    ];
156	    const r = mergeContact(POPULATED, fetched, "2026-07-02");
157	
158	    // Look only at the Mark's Email History section, not the mbox section below.
159	    const markSection = r.content.slice(
160	      r.content.indexOf("## Mark's Email History"),
161	      r.content.indexOf("## Email History")
162	    );
163	    const dates = [...markSection.matchAll(/^### (\d{4}-\d{2}-\d{2})/gm)].map((m) => m[1]);
164	    expect(dates).toEqual(["2026-06-26", "2025-09-09", "2024-01-01"]);
165	    // within the shared 2025-09-09 day, the 23:00 message sorts above the existing one
166	    expect(r.content.indexOf("same day newer")).toBeLessThan(
167	      r.content.indexOf("Re: Rose and Crown")
168	    );
169	  });
170	
171	  it("replaces the 'No direct emails found' placeholder when entries are added", () => {
172	    const r = mergeContact(
173	      PLACEHOLDER,
174	      [entry({ messageId: "m1", direction: "To client", subject: "Quote" })],
175	      "2026-07-02"
176	    );
177	
178	    expect(r.added).toBe(1);
179	    expect(r.content).not.toContain("No direct emails found");
180	    expect(r.content).toContain("Message: m1");
181	    expect(r.content).toContain("Re: Invoice"); // mbox section preserved
182	  });
183	
184	  it("skips a file with no '## Mark's Email History' heading and leaves it byte-for-byte", () => {
185	    const malformed = `---
186	last_name: Courchesne
187	first_name: Carole
188	email: "c@x.gc.ca"
189	last_updated: 2026-02-18
190	---
191	
192	
193	### 2020-10-08
194	- **Subject:** RE: Post Class
195	  - Direction: From client
