import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import {
  slugify,
  makeFilename,
  splitName,
  buildFrontmatter,
  parseArgs,
  findExistingContact,
  createContact,
} from "./create-contact";

describe("slugify", () => {
  it("lowercases and hyphenates", () => {
    expect(slugify("Harris")).toBe("harris");
    expect(slugify("Joshua Harris")).toBe("joshua-harris");
  });

  it("strips accents", () => {
    expect(slugify("Renée Ünderwood")).toBe("renee-underwood");
  });

  it("collapses non-alphanumeric runs and trims leading/trailing hyphens", () => {
    expect(slugify("  O'Brien & Sons!! ")).toBe("o-brien-sons");
  });
});

describe("splitName", () => {
  it("splits a two-word name into first/last", () => {
    expect(splitName("Joshua Harris")).toEqual({ firstName: "Joshua", lastName: "Harris" });
  });

  it("treats the last word as the surname for multi-word first names", () => {
    expect(splitName("Mary Jane Watson")).toEqual({ firstName: "Mary Jane", lastName: "Watson" });
  });

  it("puts a single word in firstName with an empty lastName", () => {
    expect(splitName("Cher")).toEqual({ firstName: "Cher", lastName: "" });
  });

  it("returns empty strings for an empty/blank name", () => {
    expect(splitName("")).toEqual({ firstName: "", lastName: "" });
    expect(splitName("   ")).toEqual({ firstName: "", lastName: "" });
  });
});

describe("makeFilename", () => {
  it("builds lastname-firstname when both are known", () => {
    expect(makeFilename("Harris", "Joshua", "josh@example.com", new Set())).toBe("harris-joshua.md");
  });

  it("falls back to the email local part when no name is known", () => {
    expect(makeFilename("", "", "some.person@example.com", new Set())).toBe("some-person.md");
  });

  it("appends the email domain on a base collision", () => {
    const used = new Set(["harris-joshua"]);
    expect(makeFilename("Harris", "Joshua", "josh@clearandloud.com", used)).toBe(
      "harris-joshua-clearandloud.md"
    );
  });

  it("appends a numeric counter when both base and domain-qualified names collide", () => {
    const used = new Set(["harris-joshua", "harris-joshua-clearandloud"]);
    expect(makeFilename("Harris", "Joshua", "josh@clearandloud.com", used)).toBe(
      "harris-joshua-clearandloud-2.md"
    );
  });
});

describe("buildFrontmatter", () => {
  it("uses a singular email: field for one address", () => {
    const fm = buildFrontmatter("Harris", "Joshua", ["josh@example.com"], "2026-07-06");
    expect(fm).toContain('email: "josh@example.com"');
    expect(fm).not.toContain("emails:");
  });

  it("uses a plural emails: list for multiple addresses", () => {
    const fm = buildFrontmatter("Email", "Multi", ["a@example.com", "b@example.com"], "2026-07-06");
    expect(fm).toContain("emails:");
    expect(fm).toContain('  - "a@example.com"');
    expect(fm).toContain('  - "b@example.com"');
    expect(fm).not.toMatch(/^email: /m);
  });

  it("includes last_name, first_name, and last_updated", () => {
    const fm = buildFrontmatter("Harris", "Joshua", ["josh@example.com"], "2026-07-06");
    expect(fm).toContain("last_name: Harris");
    expect(fm).toContain("first_name: Joshua");
    expect(fm).toContain("last_updated: 2026-07-06");
  });
});

describe("parseArgs", () => {
  it("parses name, category, and a single email", () => {
    expect(parseArgs(["--name", "Joshua Harris", "--email", "josh@example.com", "--category", "client"])).toEqual({
      name: "Joshua Harris",
      category: "client",
      emails: ["josh@example.com"],
    });
  });

  it("collects repeated --email flags", () => {
    expect(
      parseArgs(["--email", "a@example.com", "--email", "b@example.com", "--category", "friend"])
    ).toEqual({ name: "", category: "friend", emails: ["a@example.com", "b@example.com"] });
  });

  it("ignores unknown flags and trims whitespace", () => {
    expect(parseArgs(["--name", "  Joshua Harris  ", "--bogus", "x"])).toEqual({
      name: "Joshua Harris",
      category: "",
      emails: [],
    });
  });
});

describe("findExistingContact / createContact (filesystem)", () => {
  let root: string;
  let templatePath: string;

  beforeEach(() => {
    root = fs.mkdtempSync(path.join(os.tmpdir(), "create-contact-test-"));
    templatePath = path.join(root, "template.md");
    fs.writeFileSync(
      templatePath,
      "---\nlast_name:\nfirst_name:\nemail: \"\"\nlast_updated:\n---\n\n## Notes\n\n## Mark's Email History\n"
    );
  });

  afterEach(() => {
    fs.rmSync(root, { recursive: true, force: true });
  });

  it("returns null when no contact file mentions the email", () => {
    expect(findExistingContact("nobody@example.com", root)).toBeNull();
  });

  it("finds a match case-insensitively across category folders", () => {
    fs.mkdirSync(path.join(root, "friends"), { recursive: true });
    fs.writeFileSync(path.join(root, "friends", "doe-jane.md"), 'email: "Jane@Example.com"\n');
    expect(findExistingContact("jane@example.com", root)).toBe("friends/doe-jane.md");
  });

  it("creates a contact file from the template with correct frontmatter and path", () => {
    const result = createContact({
      name: "Joshua Harris",
      category: "client",
      emails: ["josh@example.com"],
      root,
      today: "2026-07-06",
      templatePath,
    });

