    const written = fs.readFileSync(path.join(root, "client", "harris-joshua.md"), "utf-8");
    expect(written).toContain("last_name: Harris");
    expect(written).toContain("first_name: Joshua");
    expect(written).toContain('email: "josh@example.com"');
    expect(written).toContain("last_updated: 2026-07-06");
